pragma solidity >=0.8.0;

contract IntSemantics {
    int64 public lastDiv;
    int64 public lastMod;
    int64 public lastShift;
    int64 public lastCast;

    // Signed division rounds toward zero: -7 / 2 == -3; -7 % 2 == -1.
    function doDivMod(int8 a, int8 b) public {
        lastDiv = a / b;
        lastMod = a % b;
    }

    // Arithmetic shift right on signed: -8 >> 1 == -4 (sign-extending).
    function doShift(int8 a) public {
        lastShift = a >> 1;
    }

    // Cast chain: int16(-1) -> uint8 truncates to 0xFF (255),
    // then uint8 -> uint64 -> int64 zero-extends: result 255, NOT -1.
    function doCast(int16 x) public {
        lastCast = int64(uint64(uint8(x)));
    }
}

pragma solidity >=0.8.13;

contract StoragePacking {
    uint8 a;
    bool b;
    int32 c;
    uint8 d;
    bytes blob;

    struct Mixed { uint8 x; uint16 y; uint64 z; bool flag; }
    Mixed internal m;

    event Wrote(uint8 a, bool b, int32 c, uint8 d);

    function writeFields(uint8 x, bool y, int32 z) public {
        a = x;
        b = y;
        c = z;
        d = x + 1;
        emit Wrote(a, b, c, d);
    }

    function setStruct(uint8 x, uint16 y, uint64 z, bool f) public {
        m = Mixed(x, y, z, f);
    }

    function setBlob(bytes memory v) public {
        blob = v;
    }

    function clearFields() public {
        delete b;
        delete c;
        delete blob;
    }

    function sumFields() public view returns (uint256) {
        return uint256(a) + uint256(d) + uint256(uint32(c)) + (b ? 1000 : 0);
    }

    function structSum() public view returns (uint256) {
        return uint256(m.x) + uint256(m.y) + uint256(m.z) + (m.flag ? 1 : 0);
    }

    function blobLen() public view returns (uint256) {
        return blob.length;
    }
}

pragma solidity >=0.8.0;
contract ValueProbe {
    uint256 public count;
    uint256 public lastValue;
    function deposit() external payable {
        count += 1;
        lastValue = msg.value;
    }
    function strict() external {
        count += 100;
    }
    function getCount() external view returns (uint256) {
        return count;
    }
    function getLast() external view returns (uint256) {
        return lastValue;
    }
}
